mapper.select:
SELECT TO_CHAR(COALESCE(a.k, b.k, c.k), ) AS period, NVL(a.paidAmt, 0) AS paidAmt, NVL(b.refundReqAmt, 0) AS refundReqAmt, NVL(c.cancelAmt, 0) AS cancelAmt, NVL(a.paidCnt, 0) AS paidCnt, NVL(b.refundReqCnt, 0) AS refundReqCnt, NVL(c.cancelCnt, 0) AS cancelCnt FROM ( SELECT AS k, SUM(p.PAY_AMOUNT) AS paidAmt, COUNT(*) AS paidCnt FROM PAYMENT p WHERE p.PAY_STATUS = 'PAID' AND p.PAID_AT IS NOT NULL
AND TO_CHAR(p.PAID_AT, 'YYYY') = #{year}
GROUP BY ) a FULL OUTER JOIN ( SELECT AS k, SUM(r.REFUND_AMOUNT) AS refundReqAmt, COUNT(*) AS refundReqCnt FROM REFUND r WHERE r.REFUND_STATUS = 'REQUESTED' AND r.REFUND_DATE IS NOT NULL
AND TO_CHAR(r.REFUND_DATE, 'YYYY') = #{year}
GROUP BY ) b ON b.k = a.k FULL OUTER JOIN ( SELECT AS k, SUM(p.PAY_AMOUNT) AS cancelAmt, COUNT(*) AS cancelCnt FROM PAYMENT p WHERE p.PAY_STATUS = 'CANCELED' AND p.REQUEST_AT IS NOT NULL
AND TO_CHAR(p.REQUEST_AT, 'YYYY') = #{year}
GROUP BY ) c ON c.k = COALESCE(a.k, b.k) ORDER BY COALESCE(a.k, b.k, c.k)

SELECT NVL(( SELECT SUM(p.PAY_AMOUNT) FROM PAYMENT p WHERE p.PAY_STATUS = 'PAID' AND p.PAID_AT IS NOT NULL
AND p.PAID_AT >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND p.PAID_AT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
), 0) AS thisPaidAmt,
0 AS prevPaidAmt,
NVL(( SELECT SUM(r.REFUND_AMOUNT) FROM REFUND r WHERE r.REFUND_STATUS = 'REQUESTED' AND r.REFUND_DATE IS NOT NULL
AND r.REFUND_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND r.REFUND_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
), 0) AS thisRefundReqAmt,
NVL(( SELECT COUNT(DISTINCT p2.ORDER_NO) FROM PAYMENT p2 WHERE p2.PAY_STATUS = 'PAID' AND p2.PAID_AT IS NOT NULL
AND p2.PAID_AT >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND p2.PAID_AT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
), 0) AS thisPaidCnt FROM DUAL

SELECT COUNT(*) FROM ( SELECT DISTINCT rp.REG_ID FROM REGISTER_PROD rp JOIN PACKAGES pkg ON pkg.PACKAGE_ID = rp.PACKAGE_ID JOIN ORDER_ITEM oi ON oi.REG_ID = rp.REG_ID JOIN ORDERS o ON o.ORDER_NO = oi.ORDER_NO JOIN ( SELECT ORDER_NO, MAX(PAID_AT) AS PAID_AT FROM PAYMENT WHERE PAY_STATUS = 'PAID' AND PAID_AT IS NOT NULL GROUP BY ORDER_NO ) pay ON pay.ORDER_NO = o.ORDER_NO WHERE pkg.PACKAGE_TITLE LIKE '%' || #{packageTitle} || '%'
AND pay.PAID_AT >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND pay.PAID_AT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
)
